/** Binary fixtures for the full-app harness (generated by ui2/scripts/build-app-harness-fixtures.mjs). */
import volumeUrl from '../fixtures/app/mni_2mm.u8?url';
import volumeMeta from '../fixtures/app/mni_2mm.json';
import verticesUrl from '../fixtures/app/lh_inflated.f32?url';
import facesUrl from '../fixtures/app/lh_inflated.i32?url';
import overlayUrl from '../fixtures/app/lh_sensorimotor.f32?url';
import surfaceMeta from '../fixtures/app/surface.json';
import zmapUrl from '../fixtures/app/zmap_2mm.f32.gz?url';
import tmapUrl from '../fixtures/app/tmap_2mm.f32.gz?url';
import atlasUrl from '../fixtures/app/atlas3_2mm.u8.gz?url';
import lutUrl from '../fixtures/app/atlas3_dseg.tsv?url';
import p3Meta from '../fixtures/app/p3_fixtures.json';

export interface VolumeFixture {
  dims: [number, number, number];
  /** Row-major 4x4 voxel -> world (RAS mm). */
  affine: number[][];
  data: Float32Array;
  range: [number, number];
  /** NIfTI header extras served by get_nifti_header_info / load_file (Phase 3 fixtures only). */
  header?: StatHeader;
}

/** NIfTI intent and description fields of a synthetic Phase 3 fixture (p3_fixtures.json). */
export interface StatHeader {
  dataType: string;
  intentCode: number;
  intentName: string;
  intentP1: number;
  intentP2: number;
  intentP3: number;
  description: string;
}

export interface SurfaceFixture {
  vertices: Float32Array;
  faces: Uint32Array;
  overlay: Float32Array;
  overlayRange: [number, number];
}

export interface HarnessFixtures {
  mni: VolumeFixture;
  stats: VolumeFixture;
  surface: SurfaceFixture;
  /** Phase 3 synthetic statistics on the MNI 2 mm grid (see build-app-harness-fixtures.mjs). */
  zmap: VolumeFixture;
  tmap: VolumeFixture;
  atlas: VolumeFixture;
  /** BIDS-style LUT sidecar text for `atlas`. */
  atlasLut: string;
}

async function fetchBuffer(url: string): Promise<ArrayBuffer> {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`fixture fetch failed: ${url} (${response.status})`);
  return response.arrayBuffer();
}

function worldOf(affine: number[][], i: number, j: number, k: number): [number, number, number] {
  return [0, 1, 2].map(
    (r) => affine[r][0] * i + affine[r][1] * j + affine[r][2] * k + affine[r][3],
  ) as [number, number, number];
}

/**
 * Signed synthetic statistic map on the MNI grid: smooth Gaussian blobs at
 * bilateral motor and visual cortex (positive) and a medial frontal
 * deactivation (negative). Peak |z| ~ 6.
 */
function buildStatsVolume(mni: VolumeFixture): VolumeFixture {
  const [nx, ny, nz] = mni.dims;
  const blobs: Array<{ c: [number, number, number]; amp: number; sigma: number }> = [
    { c: [-38, -22, 56], amp: 6.2, sigma: 7 },
    { c: [38, -22, 56], amp: 5.1, sigma: 7 },
    { c: [-12, -90, 4], amp: 5.6, sigma: 8 },
    { c: [14, -88, 6], amp: 4.8, sigma: 8 },
    { c: [0, 48, 6], amp: -4.6, sigma: 9 },
  ];
  const data = new Float32Array(nx * ny * nz);
  for (let k = 0; k < nz; k++)
    for (let j = 0; j < ny; j++)
      for (let i = 0; i < nx; i++) {
        const idx = i + nx * (j + ny * k);
        if (mni.data[idx] <= 0) continue;
        const [x, y, z] = worldOf(mni.affine, i, j, k);
        let v = 0;
        for (const b of blobs) {
          const d2 = (x - b.c[0]) ** 2 + (y - b.c[1]) ** 2 + (z - b.c[2]) ** 2;
          v += b.amp * Math.exp(-d2 / (2 * b.sigma * b.sigma));
        }
        data[idx] = Math.round(v * 1000) / 1000;
      }
  let lo = 0;
  let hi = 0;
  for (const v of data) {
    if (v < lo) lo = v;
    if (v > hi) hi = v;
  }
  return { dims: mni.dims, affine: mni.affine, data, range: [lo, hi] };
}

/** Gzip fixtures: decompress unless the dev server already did (Content-Encoding). */
async function fetchGzip(url: string): Promise<ArrayBuffer> {
  const buffer = await fetchBuffer(url);
  const head = new Uint8Array(buffer, 0, 2);
  if (head[0] !== 0x1f || head[1] !== 0x8b) return buffer;
  const stream = new Blob([buffer]).stream().pipeThrough(new DecompressionStream('gzip'));
  return new Response(stream).arrayBuffer();
}

type P3VolumeKey = 'zmap' | 'tmap' | 'atlas';

function p3Volume(key: P3VolumeKey, data: Float32Array, mni: VolumeFixture): VolumeFixture {
  const meta = p3Meta.volumes[key];
  let lo = 0;
  let hi = 0;
  for (const v of data) {
    if (v < lo) lo = v;
    if (v > hi) hi = v;
  }
  return {
    dims: mni.dims,
    affine: mni.affine,
    data,
    range: [lo, hi],
    header: {
      dataType: meta.datatype,
      intentCode: meta.intent_code,
      intentName: meta.intent_name,
      intentP1: meta.intent_p1,
      intentP2: meta.intent_p2,
      intentP3: meta.intent_p3,
      description: meta.description,
    },
  };
}

export async function loadFixtures(): Promise<HarnessFixtures> {
  const [vol, verts, faces, overlay, zmap, tmap, atlas, lut] = await Promise.all([
    fetchBuffer(volumeUrl),
    fetchBuffer(verticesUrl),
    fetchBuffer(facesUrl),
    fetchBuffer(overlayUrl),
    fetchGzip(zmapUrl),
    fetchGzip(tmapUrl),
    fetchGzip(atlasUrl),
    fetchBuffer(lutUrl),
  ]);
  const u8 = new Uint8Array(vol);
  const data = new Float32Array(u8.length);
  for (let i = 0; i < u8.length; i++) data[i] = u8[i];
  const mni: VolumeFixture = {
    dims: volumeMeta.dims as [number, number, number],
    affine: volumeMeta.affine,
    data,
    range: [0, 255],
  };
  return {
    mni,
    stats: buildStatsVolume(mni),
    surface: {
      vertices: new Float32Array(verts),
      faces: new Uint32Array(new Int32Array(faces)),
      overlay: new Float32Array(overlay),
      overlayRange: surfaceMeta.overlayRange as [number, number],
    },
    zmap: p3Volume('zmap', new Float32Array(zmap), mni),
    tmap: p3Volume('tmap', new Float32Array(tmap), mni),
    atlas: p3Volume('atlas', Float32Array.from(new Uint8Array(atlas)), mni),
    atlasLut: new TextDecoder().decode(lut),
  };
}
